\label{Th1}$L_{c,d}$ is self-adjoint in $L^{2}(\mathbb{R}^{3},c^{-1})$ and the
resolvent formula 
\begin{equation}
R_{\kappa}(c,d):=\left(  L_{c,d}-\kappa^{2}\right)  ^{-1}=R_{\kappa}+ 
\begin{bmatrix}
R_{\kappa}1_{\Omega}^{\ast} & S\!L_{\kappa} 
\end{bmatrix}
Q_{\kappa}^{-1}(c,d) 
\begin{bmatrix}
(cd-1)\Delta_{\Omega}^{\mathrm{max}}1_{\Omega}R_{\kappa}\\
\mu(d)\,\gamma_{1}R_{\kappa} 
\end{bmatrix}\label{Krein_L_cd}
\end{equation}
holds for any $\kappa\in\mathbb{C}_{+}$ such that $\kappa^{2}\in{\varrho
}(L_{c,d})$. The limit 
\[
R_{\kappa}(c,d):=\lim_{\delta\rightarrow0^{+}}R_{\kappa+i\delta} 
(c,d)\,,\qquad\kappa\in\mathbb{R}\backslash\left\{  0\right\}  \,,
\]
exists in $\mathscr{B}(H_{\alpha}^{0}(\mathbb{R}^{3}),H_{-\alpha} 
^{1}(\mathbb{R}^{3}))$ for $\alpha>3/2$. The resolvent formula (\ref{Krein_EM} 
) holds in the limit and, for any $u\in H_{\alpha}^{0}(\mathbb{R}^{3})$ one
has 
\[
\left(  \left(  -\Delta_{\Omega_{\mathrm{ex}}}\right)
\oplus\left(  -cd\Delta_{\Omega}\right)  -\kappa^{2}\right)  R_{\kappa
}(c,d)u=u\,,\qquad\kappa\in\mathbb{R}\backslash\{0\}\,.
\]
Furthermore,
\[
\sigma_{p}(L_{c,d})\cap(0,+\infty)=\varnothing\,,\quad\sigma_{ess} 
(L_{c,d})=[0,+\infty)\,,\quad\sigma_{disc}(L_{c,d})\text{ accumulates at
}-\infty\,,
\] 
\[
\sigma_{sc}(L_{c,d})=\varnothing\,,\quad\sigma_{ac}(L_{c,d})=[0,+\infty)\,.
\]
Finally, if $d_{\ell}=d_{\circ}\in(-\infty,0)\backslash\{  -1\}
$ for any index $\ell$ and $\mu^{-1}(d_{\circ})\in\sigma(K_{0})$, then
$0\in\sigma_{p}(L_{c,d})$.

\label{Theorem_inverse}If \emph{H0} holds, then
\begin{equation}
\mathbb{C}\ni\kappa\mapsto(  1-\mu(  d)  \,K_{\kappa})
^{-1} \label{Op_pencil_inv} 
\end{equation}
is a finitely meromorphic $\mathscr{B}(H^{-1/2}(\Gamma))$-valued map. In
particular:\medskip\newline$i)$ If $1\notin\sigma(  \mu({d})   K_{0})  $, then $\kappa\mapsto(  1-\mu(d)  \,K_{\kappa})  ^{-1}$ is analytic at $\kappa=0$.\medskip
\newline$ii)$ If $1\in\sigma(  \mu(  d)   K_{0})  $,
then $\kappa\mapsto(  1-\mu(  d)  \,K_{\kappa})  ^{-1}$
has a pole at $\kappa=0$.

If \emph{H0} holds and $\kappa\in\Sigma_{d}\cap\mathbb{C}_{+}$, then
\begin{equation}
\mathcal{D}_{d}=\left\{  u=u_{\circ}+S\!L_{\kappa}\left(  1-\mu(  d)
\,K_{\kappa}\right)  ^{-1}\mu(  d)  \,\gamma_{1}u_{\circ}\,,\qquad
u_{\circ}\in H^{2}(\mathbb{R}^{3})\right\}  \,. \label{dom_id} 
\end{equation}

\label{Lemma_R_k_analytic}Let $\psi\in\mathcal{C}_{c}^{\infty}(\mathbb{R} 
^{3})$, $s\in\left[  0,2\right]  $. Then $\mathbb{C}\ni\kappa\mapsto
M_{\psi}R_{\kappa}M_{\psi}$ is a $\mathscr{B}(H^{s-2}(\mathbb{R}^{3} 
),H^{s}(\mathbb{R}^{3}))$-valued analytic map.

By \cite[Theorem 3.1]{DyaZwo},
\[
\left\Vert M_{\psi}R_{\kappa}M_{\psi}\right\Vert _{L^{2}(\mathbb{R}^{3} 
),H^{2}(\mathbb{R}^{3})}\lesssim(1+|\kappa|)\,e^{L\,\text{\textrm{Im}} 
(\kappa)_{-}}\,,
\]
where $L>\text{diam}(\text{supp}(\phi))$ and $\text{\textrm{Im}}(\kappa)_{-}$
denotes the negative part. By replacing $\kappa$ with $\bar{k}$, and by
duality, one gets the same upper bound for $\left\Vert M_{\psi}R_{\kappa
}M_{\psi}\right\Vert _{H^{-2}(\mathbb{R}^{3}),L^{2}(\mathbb{R}^{3})}$. Hence,
by interpolation,
\[
\left\Vert M_{\psi}R_{\kappa}M_{\psi}\right\Vert _{H^{s-2}(\mathbb{R} 
^{3}),H^{s}(\mathbb{R}^{3})}\lesssim(1+|\kappa|)\,e^{L\,\text{\textrm{Im} 
}(\kappa)_{-}}\,.
\]
Therefore, the $\mathscr{B}(H^{s-2}(\mathbb{R}^{3}),H^{s}(\mathbb{R}^{3} 
))$-valued map $\mathbb{C}\ni\kappa\mapsto M_{\psi}R_{\kappa}M_{\psi}$ is
locally bounded and so, see, e.g., \cite[page 365]{Kato}), it is enough to
show that $\mathbb{C}\ni\kappa\mapsto\langle M_{\psi}R_{\kappa}M_{\psi
}\,u,v\rangle$ is analytic for any $u$ and $v$ belonging to dense sets in
$H^{2-s}(\mathbb{R}^{3})$ and $H^{-s}(\mathbb{R}^{3})$ respectively. Hence,
the proof is concluded by \cite[equation (5.8)]{MaPoSi JMPA 22}, which implies
the analyticity of the map
\[
\mathbb{C}\ni\kappa\mapsto\langle M_{\psi}R_{\kappa}M_{\psi}\,u,\varphi
\rangle,\qquad\quad u\in H^{s-2}(\mathbb{R}^{3})\,,\ \varphi\in\mathcal{C} 
_{c}^{\infty}(\mathbb{R}^{3})\,.
\]
\hfill

\label{Lemma_Q_Fredholm} The map ${\mathbb{C}}\ni\kappa\mapsto Q_{\kappa
}(c,d)$ is $\mathscr{B}(  L^{2}(  \Omega)  \oplus
H^{-1/2}(  \Gamma)  )  $-valued analytic. In particular,
\begin{equation}
{\mathbb{C}}\ni\kappa\mapsto 
\begin{bmatrix}
N_{\kappa} & 1_{\Omega}S\!L_{\kappa}\\
\gamma_{1}^{\mathrm{in}}N_{\kappa} & \,K_{\kappa} 
\end{bmatrix}
\label{Fredholm_cond} 
\end{equation}
is an analytic ${\mathfrak{S}}_{\infty}(  L^{2}(  \Omega)
\oplus H^{-1/2}(  \Gamma)  )  $-valued map.

We consider the operator entries of \eqref{Fredholm_cond}. Let $r>0$ be large
enough so that $\Omega\subset\subset B_{r}=\left\{  x:\left\vert x\right\vert
<r\right\}  $ and let $\psi\in\mathcal{C}_{c}^{\infty}(\mathbb{R}^{3})$ be
such that $\psi|B_{r}=1$. Since $N_{\kappa}=1_{\Omega}M_{\psi}R_{\kappa
}M_{\psi}1_{\Omega}^{\ast}$, by Lemma \ref{Lemma_R_k_analytic}, one has
$N_{\kappa}\in\mathscr{B}(L^{2}(\Omega),H^{2}(\Omega))$ and $\gamma
_{1}^{\mathrm{in}}N_{\kappa}\in\mathscr{B}\left(  L^{2}(  \Omega)
,H^{1/2}(  \Gamma)  \right)  $ for any $\kappa\in\mathbb{C}$. Then,
by the compact embeddings $H^{2}(\Omega)\hookrightarrow L^{2}(\Omega)$ and
$H^{1/2}(\Gamma)\hookrightarrow H^{-1/2}(\Gamma)$, one gets $N_{\kappa} 
\in{\mathfrak{S}}_{\infty}(L^{2}(\Omega))$ and $\gamma_{1}^{\mathrm{in} 
}N_{\kappa}\in{\mathfrak{S}}_{\infty}(L^{2}(\Omega),H^{1/2}(\Gamma))$. By
Lemma \ref{Lemma_R_k_analytic}, $\kappa\mapsto N_{\kappa}$ and $\kappa
\mapsto\gamma_{1}^{\mathrm{in}}N_{\kappa}$ are analytic in $\mathscr{B} 
(L^{2}(  \Omega)  )$ and $\mathscr{B}(L^{2}(  \Omega)
,H^{-1/2}(\Gamma))$ respectively.

By the mapping properties of the single layer potential, see e.g. \cite[Chp.
6]{McLe}, for each $\kappa\in\mathbb{C}$ one has $1_{\Omega}S\!L_{\kappa} 
\in\mathscr{B}(H^{-1/2}(\Gamma),H^{1}(  \Omega)  )$ and from the
compact embedding $H^{1}(  \Omega)  \hookrightarrow L^{2}\left(
\Omega\right)  $ there follows that $1_{\Omega}S\!L_{\kappa}\in{\mathfrak{S} 
}_{\infty}(H^{-1/2}(\Gamma),L^{2}(\Omega))$. Moreover, since $1_{\Omega
}S\!L_{\kappa}=1_{\Omega}M_{\psi}R_{\kappa}M_{\psi}\gamma_{0}^{\ast}$, by
$\gamma_{0}^{\ast}\in\mathscr{B}(H^{-1/2}(\Gamma),H^{-1}(\mathbb{R}^{3}))$ and
Lemma \ref{Lemma_R_k_analytic}, $\kappa\mapsto1_{\Omega}S\!L_{\kappa}$ is an
analytic $\mathscr{B}(H^{-1/2}(\Gamma),H^{1}(\Omega))$-valued map.

As recalled in Section \ref{Sec_Transmission}, $\kappa\mapsto K_{\kappa} 
\in\mathscr{B}(H^{-1/2}(\Gamma))$ is analytic in $\mathbb{C}$ and with values
in the set of compact operators.

The map $\kappa\mapsto Q_{\kappa}(c,d)$ is analytic in $\mathbb{C}$ and
recasts in the form 
\begin{equation}
Q_{\kappa}(c,d)= 
\begin{bmatrix}
cd & 0\\
0 & 1
\end{bmatrix}
\left(  \, 
\begin{bmatrix}
1 & 0\\
0 & 1
\end{bmatrix}
+ 
\begin{bmatrix}
\frac{1}{cd}(cd-1)\kappa^{2} & 0\\
0 & -\mu(  d)  \,
\end{bmatrix} 
\begin{bmatrix}
N_{\kappa} & 1_{\Omega}S\!L_{\kappa}\\
\gamma_{1}^{\mathrm{in}}N_{\kappa} & \,K_{\kappa} 
\end{bmatrix}
\,\right)  \,. \label{Q_cd_id} 
\end{equation}
By the result of the Lemma \ref{Lemma_Q_Fredholm}, the meromorphic Fredholm
theory (see \cite[Theorem XIII.13]{ReSi IV}) applies to the r.h.s. of
(\ref{Q_cd_id}). Hence: either $\kappa\mapsto Q_{\kappa}^{-1}\left(
c,d\right)  \in\mathscr{B}\left(  L^{2}(\Omega)\oplus H^{-1/2}\left(
\Gamma\right)  \right)  $ is finitely-meromorphic in $\mathbb{C}$ or
$Q_{\kappa}(c,d)$ is nowhere invertible. We next show that this last statement
leads to a contradiction.

Assume that $Q_{\kappa}(c,d)$ is not invertible for all $\kappa\in\mathbb{C}$.
By the Fredholm alternative, $\ker Q_{\kappa}(  c,d)  \neq\left\{
(0,0)\right\}  $, i.e., there exists a non-trivial $\left(  u(\kappa
),\varphi(\kappa)\right)  \in L^{2}(\Omega)\oplus H^{-1/2}(\Gamma)$ solving
the equation
\[
Q_{\kappa}(c,d)\left(  u(\kappa),\varphi(  \kappa)  \right)
=(0,0)\,,
\]
equivalently,
\begin{equation}
\left\{
\begin{array}
[c]{l} 
\left(  cd+(cd-1)\kappa^{2}N_{\kappa}\right)  u(\kappa)+(cd-1)\kappa
^{2}1_{\Omega}S\!L_{\kappa}\varphi(\kappa)=0\,,\\
-\mu(  d)  \,\gamma_{1}^{\mathrm{in}}N_{\kappa}u(\kappa)+\left(
1-\mu(  d)  \,K_{\kappa}\right)  \varphi(\kappa)=0\,.
\end{array}
\right.  \label{Q_ker_eq} 
\end{equation}
We next assume $\kappa\in\Sigma_{d}\backslash\{0\}$ defined in (\ref{sigma-d} 
). Notice that 
\[
\kappa\in\Sigma_{d}\quad\Leftrightarrow\quad\ker\left(  1-\mu(  d)
\,K_{\kappa}\right)  =\{0\}\,.
\]
From the second equation, we have 
\begin{equation}
\varphi(\kappa)=(  1-\mu(  d)  \,K_{\kappa})  ^{-1} 
\mu(  d)  \,\gamma_{1}^{\mathrm{in}}N_{\kappa}u(\kappa)\,.
\label{Q_ker_cond} 
\end{equation}
Since $\left(  u(\kappa),\varphi(\kappa)\right)  \neq\left(  0,0\right)  $,
this implies: $u(\kappa)\neq0$. Using (\ref{d_sign_ass}) and (\ref{Q_ker_cond} 
), the above system rephrase as 
\begin{equation}
\left\{
\begin{array}
[c]{l} 
\Psi_{\kappa}\,u(\kappa)=\frac{1}{\kappa^{2}}\,\frac{cd}{1-cd}\,u(\kappa)\,,\\
\varphi(\kappa)=(  1-\mu(  d)  \,K_{\kappa})  ^{-1} 
\mu(  d)  \,\gamma_{1}^{\mathrm{in}}N_{\kappa}u(\kappa)\,,
\end{array}
\right.  \label{Q_ker_eq_1} 
\end{equation}
where $\Psi_{\kappa}\in\mathscr{B}(L^{2}(\Omega))$ is defined by
\[
\Psi_{\kappa}:=N_{\kappa}+1_{\Omega}S\!L_{\kappa}\left(  1-\mu\left(
{d}\right)  \,K_{\kappa}\right)  ^{-1}\mu(  d)  \,\gamma
_{1}^{\mathrm{in}}N_{\kappa}\,.
\]
Therefore, $u(\kappa)$ is an eigenvectors of $\Psi_{\kappa}$. Let us introduce
$\psi(\kappa)\in L^{2}(\mathbb{R}^{3})$ defined by 
\[
\psi(\kappa):=R_{\kappa}1_{\Omega}^{\ast}u(\kappa)+S\!L_{\kappa}\left(
1-\mu(  d)  \,K_{\kappa}\right)  ^{-1}\mu(  d)
\,\gamma_{1}R_{\kappa}1_{\Omega}^{\ast}u(\kappa)u(\kappa)\,.
\]
By (\ref{dom_id}) (with $u_{\circ}=R_{\kappa}1_{\Omega}^{\ast}u(\kappa)$), one has
$\psi(\kappa)\in\mathcal{D}_{d}$. By (\ref{Q_ker_eq_1}), it results 
\begin{equation}
\psi(\kappa)|\Omega=\Psi_{\kappa}u(\kappa)\,. \label{psi_def} 
\end{equation}
Since $\mathrm{ran}(S\!L_{\kappa})\cap H^{2}(\mathbb{R}^{3})=\{0\}$ and
$u(\kappa)\neq0$, one has $\psi(\kappa)\neq0$. Furthermore, 
\[
\left.  \left(  L_{c,d}-\kappa^{2}\right)  \psi(\kappa)\right\vert
\Omega_{\mathrm{ex}}=\left.  \left(  -\Delta-\kappa
^{2}\right)  \psi(\kappa)\right\vert \mathbb{R}^{3}\backslash\overline{\Omega
}=\left.  1_{\Omega}^{\ast}u(\kappa))\right\vert \mathbb{R}^{3}\backslash
\overline{\Omega}=0\,,
\]
and
\begin{align*}
\left(  L_{c,d}-\kappa^{2}\right)  \psi(\kappa)|\Omega=  &  (-cd\,\Delta
-\kappa^{2})\psi(\kappa)|\Omega=cd\,(-\Delta-\kappa^{2})\psi(\kappa
)|\Omega-(1-cd)\,\kappa^{2}\psi(\kappa)|\Omega\\
=  &  cd\,u(\kappa)-(1-cd)\,\kappa^{2}\psi(\kappa)|\Omega=0\,.
\end{align*}
Hence, for any $\kappa\in\Sigma_{d}\backslash\left[  0,+\infty\right)  $,
$\psi(\kappa)$ is an eigenfunction of $L_{c,d}$ with eigenvalue $\kappa^{2}$.
However, since $L_{c,d}$ is symmetric, this is only possible when $\kappa
^{2}\in\mathbb{R}$.

If $1\notin\sigma\left(  \mu(  d)   K_{0}\right)  $,
the\ results in $(i)$-Theorem \ref{Theorem_inverse} applies and $\kappa\mapsto
(  1-\mu(  d)  \,K_{\kappa})  ^{-1}$ is
analytic at $\kappa=0$. The Schur complement of the second diagonal entry is
(\ref{Q_cd}) is 
\[
C_{\kappa}:=cd+({cd}-1)\kappa^{2}\left(  1+1_{\Omega}S\!L_{\kappa}\left(
1-\mu(  d)  \,K_{\kappa}\right)  ^{-1}\mu(  d)
\,\gamma_{1}^{\mathrm{in}}\right)  N_{\kappa}\,.
\]
Since $\kappa\mapsto C_{\kappa}$ is analytic in a neighborhood of $\kappa=0$
and $C_{0}$ has bounded inverse, $\kappa\mapsto C_{\kappa}^{-1}$ is analytic
in a neighborhood of $\kappa=0$ as well. Then $(i)$ follows using Schur's
complement argument.

If $1\in\sigma\left(  \mu(  d)   K_{0}\right)  $, by
$(ii)$-Theorem \ref{Theorem_inverse}, $\left(  1-\mu(  d)
 K_{0}\right)  $ has non-trivial kernel. Hence, if $\varphi\in\ker\left(
1-\mu(  d)   K_{0}\right)  $, then $(0,\varphi)\in\ker
Q_{0}(c,d)$.

\label{Theorem_Krein_EM}$L_{c,d}$ is self-adjoint in $L^{2}(\mathbb{R} 
^{3},c^{-1})$ and the resolvent formula 
\begin{equation}
R_{\kappa}(  c,d)  :=\left(  L_{c,d}-\kappa^{2}\right)
^{-1}=R_{\kappa}+ 
\begin{bmatrix}
R_{\kappa}1_{\Omega}^{\ast} & S\!L_{\kappa} 
\end{bmatrix}
Q_{\kappa}^{-1}(  c,d)
\begin{bmatrix}
(cd-1)\Delta_{\Omega}^{\mathrm{max}}1_{\Omega}R_{\kappa}\\
\mu(  d)  \,\gamma_{1}R_{\kappa} 
\end{bmatrix}
\label{Krein_EM} 
\end{equation}
holds for any $\kappa\in\mathbb C_{+}$ such that $\kappa^{2}\in{\varrho}(L_{c,d})$.

Most of the results from \cite[Sec. 4]{MaPo Acoustic 26} apply our setting
after replacing the coefficients $\rho_{\ell}$ (there denoting the acoustic
densities of $\Omega_{\ell}$) with $d_{\ell}^{-1}$ (c.f. the definitions
(\ref{c_def}) with \cite[eq. (1.2)]{MaPo Acoustic 26}). In particular, from
\cite[eqs. (4.10) and (4.11) ]{MaPo Acoustic 26} there follows that
(\ref{Q_Krein}) is invertible if and only if $Q_{\kappa}^{-1}(c,d)$ exists and
in such a case one has (c.f. with \cite[proof of Theorem 4.6]{MaPo Acoustic
26})\emph{ } 
\begin{align*}
&G_{\kappa}(1+(B_{1}(cd)\oplus B_{2}(d\,))\tau G_{\kappa})^{-1}(B_{1}(cd)\oplus
B_{2}(d\,))G_{-\bar{\kappa}}^{\ast}\\
=& 
\begin{bmatrix}
R_{\kappa}1_{\Omega}^{\ast} & S\!L_{\kappa} 
\end{bmatrix}
Q_{\kappa}^{-1}(c,d) 
\begin{bmatrix}
(cd-1)1_{\Omega}^{\ast}\Delta_{\Omega}^{\mathrm{max}}1_{\Omega}R_{\kappa}\\
\mu(  d)  \,\gamma_{1}R_{\kappa} 
\end{bmatrix}
.
\end{align*}
Then, by \cite[Theorem 4.2]{MaPo Acoustic 26}, if $Q_{\kappa}^{-1}(c,d)$ for
some $\kappa$ then there exists a closed operator $\hat{L}$ with resolvent
given by the right hand side of \eqref{Krein_EM}; such a resolvent exists (by
the same arguments as in \cite[Theorem 2.19 and Remark 2.20]{CFP}) for any
$\kappa\in{\mathbb{C}}_{+}$ such that $\kappa^{2}\in{\varrho}(\hat{L} 
)\cap\mathbb{C}\backslash\lbrack0,+\infty)$. Since, by Theorem
\ref{Theorem_Q_full}, $Q_{\kappa}^{-1}(c,d)$ exists for $\kappa\in\mathbb{C}$
in an open set, $\widehat{L}$ exists, his resolvent is provided by the r.h.s.
of (\ref{Krein_EM}) and, by \cite[Theorem 4.3]{MaPo Acoustic 26}, it coincides
with $L_{c,d}$. Furhtermore, since $L_{c,d}$ is symmetric, $\pm i\in{\varrho
}(L_{c,d})$ and so $\mathrm{ran}(L_{c,d}\pm i)=\mathrm{dom}((L_{c,d}\pm
i)^{-1})=L^{2}(\mathbb{R}^{3},c^{-1})$. In conclusion, $L(c,d)$ is self-adjoint.

By
\[
\left(  (-\Delta_{\Omega_{\mathrm{ex}}}^{\mathrm{max} 
})\oplus(-cd\Delta_{\Omega}^{\mathrm{max}})-\kappa^{2}\right)  (L_{c,d} 
-\kappa^{2})^{-1}=1
\]
and by 

\[
\left(  (-\Delta_{\Omega_{\mathrm{ex}}}^{\mathrm{max} 
})\oplus(-cd\Delta_{\Omega}^{\mathrm{max}})-\kappa^{2}\right)  R_{\kappa
}u=\left(  \chi_{\Omega_{\mathrm{ex}}}+cd\chi_{\Omega
}\right)  u-(1-cd)\kappa^{2}\chi_{\Omega}R_{\kappa}u\,,
\]
there follows
\begin{align}
&  \left(  (-\Delta_{\Omega_{\mathrm{ex}}}^{\mathrm{max} 
})\oplus(-cd\Delta_{\Omega}^{\mathrm{max}})-\kappa^{2}\right)
\begin{bmatrix}
R_{\kappa}1_{\Omega}^{\ast} & S\!L_{\kappa} 
\end{bmatrix}
Q_{\kappa}^{-1}(  c,d)
\begin{bmatrix}
(cd-1)\Delta_{\Omega}^{\mathrm{max}}1_{\Omega}R_{\kappa}u\\
\mu(  d)  \,\gamma_{1}R_{\kappa}u
\end{bmatrix}
\nonumber\\
=  &  u-\left(  \chi_{\Omega_{\mathrm{ex}}} 
+cd\chi_{\Omega}\right)  u-\left(  1-cd\right)  \kappa^{2}\chi_{\Omega
}R_{\kappa}u=\left(  1-cd\right)  \chi_{\Omega}\left(  1-\kappa^{2}R_{\kappa
}\right)  u\,. \label{Krein_diff_id} 
\end{align}

\label{Lemma_LAP} The limit 
\begin{equation}
R_{\kappa}(  c,d)  :=\lim_{\delta\rightarrow0^{+} 
}R_{\kappa+i\delta}(  c,d)  \,, \qquad \kappa\in\mathbb R\backslash \{\kappa\in\mathbb R:\ker(Q_{\kappa}(c,d))\not=\{0\}\}\,,\label{LAP_L_cd} 
\end{equation}
exists in ${\mathscr B}(  H_{\alpha } 
^{0}(  \mathbb{R}^{3})  ,H_{-\alpha }^{1}(  \mathbb{R}^{3}))$  for $\alpha >3/2$. The resolvent formula (\ref{Krein_EM}) holds in
the limit and, for any  $u\in H_{\alpha }^{0}(  \mathbb{R}^{3})$ one has 
\begin{equation}
\big(  (  -\Delta_{\Omega_{\+}})  \oplus(
-cd\Delta_{\Omega})  -\kappa^{2}\big)  R_{\kappa}(  c,d)
u=u\,,\qquad   
\kappa\in\mathbb R\backslash \{\kappa\in\mathbb R:\ker(Q_{\kappa}(c,d))\not=\{0\}\}
\,. \label{LAP_L_cd_id} 
\end{equation}

By \eqref{Krein_EM}), for any $\kappa\in\mathbb R$ and $\delta>0$, there holds
\[
R_{\kappa+i\delta}(  c,d)  =R_{\kappa+i\delta } 
+\begin{bmatrix}R_{\kappa+i\delta}1_{\Omega}^{*}&S\!L_{\kappa+i\delta}\end{bmatrix}
Q_{\kappa+i\delta}^{-1}(  c,d)
\begin{bmatrix}(  cd-1)1_{\Omega
}^{\ast}\Delta_{\Omega}^{\mathrm{max}}1_{\Omega}R_{\kappa+i\delta}
\\
\tilde{d}\,\gamma_{1} R_{\kappa+i\delta}
\end{bmatrix}.
\]
By (\ref{LAP})-(\ref{SL_LAP}), the r.h.s. of this equation has limit in
${\mathscr B}\left(  H_{\alpha }^{0}(  \mathbb{R}^{3})  ,H_{-\alpha } 
^{1}(  \mathbb{R}^{3})  \right)  $ with the possible exception of
the real poles of $\kappa\mapsto  Q_{\kappa}^{-1}(  c,d)  $, i.e., for the real $\kappa$'s such that $\ker(Q_{\kappa}(c,d))\not=\{0\}$. Hence, the limit  in
(\ref{LAP_L_cd}) is  defined through (\ref{Krein_EM}) and the relation
(\ref{LAP_L_cd_id}) follows by taking the limit in 
(\ref{Krein_diff_id}).

\label{theorem_spectrum}$\left.  {}\right.  \medskip$\newline$i)$ $\sigma
_{p}(L_{c,d})\cap\left(  0,+\infty\right)  =\varnothing\,$.\medskip
\newline$ii)$ $\sigma_{ess}(L_{c,d})=[0,+\infty)$ and $\sigma_{disc}(L_{c,d})$
accumulates at $-\infty\,$.\medskip\newline$iii)$ $\sigma_{sc}(L_{c,d} 
)=\varnothing$ and $\sigma_{ac}(L_{c,d})=\left[  0,+\infty\right)  \,$.

$i)$ Let $\lambda>0$ and $u_{\lambda}\in\mathcal{D}_{d}$ be such that
$L_{c,d}u_{\lambda}=\lambda u_{\lambda}$. Since $L_{c,d}\subset(-\Delta
_{\Omega_{\mathrm{ex}}}^{\mathrm{max}})\oplus
(-cd\Delta_{\Omega}^{\mathrm{max}})$, it results
\[
(\Delta+\lambda)u_{\lambda}|\Omega_{\mathrm{ex}}=0\,.
\]
By Rellich's estimate (see, e.g., \cite[Corollary 4.8]{Leis}): $\left.
u_{\lambda}\right\vert B^{c}=0$ for any open ball $B\supset\overline{\Omega}$.
Hence, by the unique continuation property (see, e.g., \cite[Section
4.3]{Leis}), $\left.  u_{\lambda}\right\vert \mathbb{R}^{3}\backslash
\overline{\Omega}=0$ and so $\gamma_{0}^{+}u_{\lambda}=\gamma_{1} 
^{+}u_{\lambda}=0$. Hence, the boundary conditions in $\mathcal{D}_{d}$ imply 
\[
\left\{
\begin{array}
[c]{l} 
(cd\,\Delta+\lambda)u_{\lambda}|\Omega=0\,,\\
\gamma_{0}^{\mathrm{in}}=\gamma_{1}^{\mathrm{in}}u=0\,,
\end{array}
\right.
\]
which admits only the trivial solution. Therefore, $u_{\lambda}=0$.

$ii)$ Since $S\!L_{\kappa}\in\mathscr{B}(H^{-3/2}(\Gamma),L^{2}(\mathbb{R} 
^{3}))$ and $H^{-1/2}(\Gamma)\hookrightarrow H^{-3/2}(\Gamma)$ with compact
embedding, one has $S\!L_{\kappa}\in\mathfrak{S}_{\infty}(H^{-1/2} 
(\Gamma),L^{2}(\mathbb{R}^{3}))$. By $R_{\kappa}\in\mathscr{B}\left(
L^{2}(  \mathbb{R}^{3})  ,H^{2}(  \mathbb{R}^{3})
\right)  $ and by the compact embedding $H^{2}(\Omega)\hookrightarrow
L^{2}(\Omega)$, one has $1_{\Omega}R_{\kappa}\in\mathfrak{S}_{\infty} 
(L^{2}(\mathbb{R}^{3}),L^{2}(\Omega))$; then, by duality, $R_{\kappa} 
1_{\Omega}^{\ast}\in\mathfrak{S}_{\infty}(L^{2}(\Omega),L^{2}(\mathbb{R} 
^{3}))$. Hence, by \eqref{Krein_EM}, the resolvent difference $\left(
L_{c,d}-\kappa^{2}\right)  ^{-1}-R_{\kappa}$, is compact as well. Therefore,
the Weyl theorem applies (see, e.g., \cite[Th. XIII.14]{ReSi IV}) and
$\sigma_{ess}(L_{c,d})=\sigma_{ess}(-\Delta)=[0,+\infty)$. Since $L_{c,d}$ is
unbounded from below and $\sigma_{disc}(L_{c,d})\subset\mathbb{R} 
\backslash\sigma_{ess}(L_{c,d})=(-\infty,0)$, it accumulates at $-\infty$.

$iii)$ Since $E:=\{\kappa\in \mathbb R:
\ker(Q_{\kappa}(c,d))\not=\{0\}\}$ is discrete, $E^{2}:=\{\kappa^{2}:\kappa\in E\}\subset
[0,+\infty)$ is discrete as well and $[0,+\infty)\backslash E^{2}$ is the (almost countable) union of open intervals $I_{n}$. Now, we argue as in 
 \cite[Proof of Theorem 6.1]{Agmon}. Hence, we consider the map 
$I_{n}\ni\lambda\mapsto\left\langle f,P_{\lambda}
f\right\rangle $,, where  
$f\in L^{2}(\mathbb R^{3},c^{-1})_{pp}^{\bot}$,  $P_{\lambda
}    $ is the spectral resolution of the identity
associated with $L_{c,d}$ and $  
